create table if not exists cities(id uuid primary key default gen_random_uuid(),realm text not null default 'LIVE' check(realm in('LIVE','DEMO')),name text not null,state text not null,country text not null default 'India',slug text not null,timezone text not null default 'Asia/Kolkata',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(realm,slug));
insert into cities(name,state,slug) values('Dhenkanal','Odisha','dhenkanal'),('Bhubaneswar','Odisha','bhubaneswar'),('Cuttack','Odisha','cuttack') on conflict do nothing;
create table if not exists pujas(id uuid primary key default gen_random_uuid(),realm text not null default 'LIVE' check(realm in('LIVE','DEMO')),slug text not null,name text not null,short_description text not null default '',full_description text not null default '',duration_minutes integer check(duration_minutes>0),samagri_required boolean not null default false,samagri_available boolean not null default false,online_available boolean not null default false,temple_available boolean not null default false,notes text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(realm,slug));
create table if not exists puja_packages(id uuid primary key default gen_random_uuid(),puja_id uuid not null references pujas(id),name text not null,description text not null default '',duration_minutes integer not null check(duration_minutes>0),service_amount_paise bigint not null check(service_amount_paise>=0),pujari_amount_paise bigint not null check(pujari_amount_paise>=0),platform_fee_paise bigint not null default 0 check(platform_fee_paise>=0),tax_paise bigint not null default 0 check(tax_paise>=0),active boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists pujari_services(provider_id text not null references providers(id),puja_id uuid not null references pujas(id),price_adjustment_paise bigint not null default 0,modes text[] not null default '{IN_PERSON}',active boolean not null default true,primary key(provider_id,puja_id));
create table if not exists service_areas(id uuid primary key default gen_random_uuid(),city_id uuid not null references cities(id),name text not null,pincode text,active boolean not null default true);
create table if not exists provider_service_areas(provider_id text not null references providers(id),service_area_id uuid not null references service_areas(id),travel_fee_paise bigint not null default 0 check(travel_fee_paise>=0),primary key(provider_id,service_area_id));
alter table providers add column if not exists verification_status text not null default 'PENDING' check(verification_status in('PENDING','VERIFIED','REJECTED','SUSPENDED'));
alter table providers add column if not exists city_id uuid references cities(id);
alter table providers add column if not exists realm text not null default 'LIVE' check(realm in('LIVE','DEMO'));
alter table bookings drop constraint if exists bookings_status_check;
alter table bookings add constraint bookings_status_check check(status in('REQUESTED','PENDING_CONFIRMATION','AWAITING_CONFIRMATION','CONFIRMED','PUJARI_ASSIGNED','IN_PROGRESS','COMPLETED','CANCELLED','REJECTED','REFUND_PENDING','REFUNDED'));
alter table bookings add column if not exists realm text not null default 'LIVE' check(realm in('LIVE','DEMO'));
alter table bookings add column if not exists city_id uuid references cities(id);
alter table bookings add column if not exists puja_id uuid references pujas(id);
alter table bookings add column if not exists package_id uuid references puja_packages(id);
alter table bookings add column if not exists language text;
alter table bookings add column if not exists ritual_notes text;
alter table bookings add column if not exists idempotency_key text;
alter table bookings add column if not exists service_amount_paise bigint not null default 0;
alter table bookings add column if not exists pujari_amount_paise bigint not null default 0;
alter table bookings add column if not exists samagri_amount_paise bigint not null default 0;
alter table bookings add column if not exists platform_fee_paise bigint not null default 0;
alter table bookings add column if not exists travel_fee_paise bigint not null default 0;
alter table bookings add column if not exists discount_paise bigint not null default 0;
alter table bookings add column if not exists tax_paise bigint not null default 0;
alter table bookings add column if not exists gross_amount_paise bigint not null default 0;
alter table bookings add column if not exists refund_amount_paise bigint not null default 0;
alter table bookings add column if not exists rebook_parent_id bigint references bookings(id);
create unique index if not exists bookings_idempotency_unique on bookings(idempotency_key) where idempotency_key is not null;
create table if not exists booking_assignments(id uuid primary key default gen_random_uuid(),booking_id bigint not null references bookings(id),provider_id text not null references providers(id),assigned_by uuid references app_users(id),assigned_at timestamptz not null default now(),unassigned_at timestamptz,response text not null default 'PENDING' check(response in('PENDING','ACCEPTED','DECLINED','EXPIRED')),responded_at timestamptz,reason text);
create unique index if not exists booking_active_assignment_unique on booking_assignments(booking_id) where unassigned_at is null;
create table if not exists booking_status_history(id bigint generated always as identity primary key,booking_id bigint not null references bookings(id),from_status text,to_status text not null,actor_user_id uuid references app_users(id),reason text,created_at timestamptz not null default now());
create table if not exists booking_items(id uuid primary key default gen_random_uuid(),booking_id bigint not null references bookings(id),type text not null,description text not null,quantity integer not null default 1 check(quantity>0),unit_amount_paise bigint not null,total_amount_paise bigint not null);
create table if not exists payments(id uuid primary key default gen_random_uuid(),booking_id bigint not null references bookings(id),provider text not null check(provider in('MANUAL','RAZORPAY')),method text not null check(method in('PAY_ON_CONFIRMATION','ONLINE_PAYMENT','CASH')),provider_payment_id text,status text not null,amount_paise bigint not null check(amount_paise>=0),currency text not null default 'INR',recorded_by uuid references app_users(id),created_at timestamptz not null default now());
create table if not exists refunds(id uuid primary key default gen_random_uuid(),payment_id uuid not null references payments(id),amount_paise bigint not null check(amount_paise>0),reason text not null,status text not null,provider_refund_id text,created_at timestamptz not null default now());
create table if not exists pujari_settlements(id uuid primary key default gen_random_uuid(),provider_id text not null references providers(id),amount_paise bigint not null check(amount_paise>=0),status text not null,reference text,recorded_by uuid references app_users(id),paid_at timestamptz,created_at timestamptz not null default now());
create table if not exists merchants(id uuid primary key default gen_random_uuid(),realm text not null default 'LIVE',name text not null,contact text,address text,city_id uuid references cities(id),active boolean not null default true,notes text);
create table if not exists samagri_fulfilments(id uuid primary key default gen_random_uuid(),booking_id bigint not null unique references bookings(id),merchant_id uuid references merchants(id),status text not null check(status in('NOT_REQUIRED','REQUESTED','ASSIGNED','PREPARING','READY','DELIVERED','CANCELLED')),amount_paise bigint not null default 0,updated_at timestamptz not null default now());
create table if not exists reviews(id uuid primary key default gen_random_uuid(),booking_id bigint not null unique references bookings(id),customer_user_id uuid not null references app_users(id),provider_id text not null references providers(id),rating integer not null check(rating between 1 and 5),punctuality integer check(punctuality between 1 and 5),professionalism integer check(professionalism between 1 and 5),service_experience integer check(service_experience between 1 and 5),body text,moderation_status text not null default 'PENDING',created_at timestamptz not null default now());
create table if not exists customer_addresses(id uuid primary key default gen_random_uuid(),customer_user_id uuid not null references app_users(id),label text not null,address text not null,pincode text,city_id uuid references cities(id),is_default boolean not null default false,created_at timestamptz not null default now());
create table if not exists favorite_pujaris(customer_user_id uuid not null references app_users(id),provider_id text not null references providers(id),created_at timestamptz not null default now(),primary key(customer_user_id,provider_id));
create table if not exists customer_pujari_notes(id uuid primary key default gen_random_uuid(),customer_user_id uuid not null references app_users(id),provider_id text not null references providers(id),author_user_id uuid not null references app_users(id),body text not null,created_at timestamptz not null default now());
create table if not exists matching_configs(id uuid primary key default gen_random_uuid(),realm text not null default 'LIVE',version integer not null,service_weight integer not null,geography_weight integer not null,language_weight integer not null,specialization_weight integer not null,rating_weight integer not null,completion_weight integer not null,acceptance_weight integer not null,relationship_weight integer not null,active boolean not null default false,created_at timestamptz not null default now(),check(service_weight+geography_weight+language_weight+specialization_weight+rating_weight+completion_weight+acceptance_weight+relationship_weight=100),unique(realm,version));
insert into matching_configs(version,service_weight,geography_weight,language_weight,specialization_weight,rating_weight,completion_weight,acceptance_weight,relationship_weight,active) values(1,30,20,15,10,10,5,5,5,true) on conflict do nothing;
create table if not exists notification_events(id uuid primary key default gen_random_uuid(),booking_id bigint references bookings(id),event_type text not null,recipient_user_id uuid references app_users(id),payload jsonb not null default '{}',status text not null default 'PENDING',created_at timestamptz not null default now());
create table if not exists analytics_manual_inputs(id uuid primary key default gen_random_uuid(),realm text not null default 'LIVE',metric_key text not null,value numeric not null,period_start date,period_end date,recorded_by uuid references app_users(id),created_at timestamptz not null default now());
create table if not exists seed_runs(id uuid primary key default gen_random_uuid(),realm text not null check(realm='DEMO'),version text not null unique,checksum text not null,created_at timestamptz not null default now());
